const k=new URLSearchParams(location.search).get('scheme')||'a';const data={a:['A 石墨编辑室','参考图的深灰层次、连续分区与留白'],b:['B 暗场悬浮','工具与记录分离，四向菜单采用方形构图'],c:['C 浅色工作台','深色观看区与浅色记录纸面，明确区分观察和整理']};document.body.className=k;document.getElementById('board').innerHTML='<header><h1>'+data[k][0]+'</h1><span>'+data[k][1]+'</span></header><div class="hero"><iframe src="'+k+'.html?state=records"></iframe></div><div class="details"><section class="detail"><h2>观看轮盘</h2><div class="wheel"><span class="up">标注</span><span class="down">记录</span><span class="left">片段</span><span class="right">循环</span></div><p class="hint">长按显示 · 甩向执行 · 回中心取消</p></section><section class="detail"><h2>统一标注 / 圈画工具</h2><div class="editor">火焰边缘散开，主体轮廓开始消失。<div class="hint">Enter 保存　Shift + Enter 换行</div></div><div class="smallwheel"><span>撤销</span><span>类型 ›</span><span>颜色</span><span>橡皮</span></div><p class="hint">工具为轮盘选项的展开细节，非新增常驻工具条。</p></section><section class="detail"><h2>时间轴 / 片段范围</h2><div class="track"><span class="range"></span><div class="points"><i></i><i></i><i></i><i></i></div></div><p class="note">细线承载播放进度<br>标注点用于跳转，短竖线标明片段头尾<br>不显示时间数字与帧数</p><p class="hint">局部放大展示；实际观看时保持细窄。</p></section></div><footer>HTML / CSS 静态设计 · 上方为记录展开，下方为细节放大 · 窗口控件包含最小化、最大化和关闭</footer>';window.DESIGN_READY=new Promise(resolve=>document.querySelector('iframe').addEventListener('load',()=>resolve(),{once:true}));